SELECT CORP_USR_ID     AS "corpUsrId",
       USER_NAME       AS "userName",
       CORP_USR_GRP_ID AS "corpUsrGrpId"
FROM TRX_TASK_CANDIDATE
WHERE TRX_TASK_ID = #{taskId}
  AND STAGE_SEQ = #{stageSeq}
  AND USER_ID = #{userId}

SELECT COUNT(*)
FROM TRX_TASK_ACTION
WHERE TRX_TASK_ID = #{taskId}
  AND STAGE_SEQ = #{stageSeq}
  AND ACTOR_USER_ID = #{actorUserId}
